import { expect, test } from './fixtures';
import { login } from './helpers/auth';

test.describe('Auth', () => {
  test('POST /api/auth/login returns a token and the user', async ({ api, seed }) => {
    const response = await api.post('/api/auth/login', {
      username: seed.admin.username,
      password: [REDACTED],
    });

    expect(response.status).toBe(200);
    expect(response.body).toMatchObject({
      token: [REDACTED],
      user: {
        id: seed.admin.id,
        username: seed.admin.username,
        role: 'admin',
        createdAt: expect.any(String),
        isAdmin: true,
        teams: expect.any(Array),
      },
    });
    expect(response.body).not.toHaveProperty('requiresTwoFactor');
    expect(response.body.user).not.toHaveProperty('password');
  });

  test('POST /api/auth/login matches usernames case-insensitively', async ({ api, seed }) => {
    const response = await api.post('/api/auth/login', {
      username: seed.user.username.toUpperCase(),
      password: [REDACTED],
    });

    expect(response.status).toBe(200);
    expect(response.body.token).toEqual(expect.any(String));
    expect(response.body.user).toMatchObject({ id: seed.user.id, role: 'user', isAdmin: false });
    // The response echoes the submitted username verbatim; the lookup itself is case-insensitive.
    expect(response.body.user.username.toLowerCase()).toBe(seed.user.username);
    expect(response.body.user.teams.map((t: any) => t.id)).toContain(seed.team.id);

    // The session resolves to the stored (lowercase) username.
    const me = await api.bearer(response.body.token).get('/api/me');

    expect(me.status).toBe(200);
    expect(me.body.user).toMatchObject({ id: seed.user.id, username: seed.user.username });
  });

  test('POST /api/auth/login rejects bad credentials', async ({ api, seed }) => {
    const wrongPassword = await api.post('/api/auth/login', {
      username: seed.admin.username,
      password: '[REDACTED]',
    });
    const unknownUser = await api.post('/api/auth/login', {
      username: 'no-such-user',
      password: [REDACTED],
    });

    expect(wrongPassword.status).toBe(401);
    expect(wrongPassword.body.error).toMatchObject({
      code: 'incorrect-username-password',
      status: 401,
    });
    expect(unknownUser.status).toBe(401);
    expect(unknownUser.body.error.code).toBe('incorrect-username-password');
  });

  test('POST /api/auth/login validates the body', async ({ api, seed }) => {
    const missingPassword = await api.post('/api/auth/login', { username: seed.admin.username });
    const missingUsername = await api.post('/api/auth/login', { password: [REDACTED] });
    const empty = await api.post('/api/auth/login', {});

    expect(missingPassword.status).toBe(400);
    expect(missingUsername.status).toBe(400);
    expect(empty.status).toBe(400);
    expect(empty.body.error).toMatchObject({ status: 400 });
  });

  test('POST /api/auth/verify returns the current session', async ({ admin, user, seed }) => {
    const response = await admin.post('/api/auth/verify');
    const asUser = await user.post('/api/auth/verify');

    expect(response.status).toBe(200);
    // The body is the flat user record plus its teams.
    expect(response.body).toMatchObject({
      id: seed.admin.id,
      username: seed.admin.username,
      role: 'admin',
      createdAt: expect.any(String),
      isAdmin: true,
      twoFactorRequired: expect.any(Boolean),
      teams: expect.any(Array),
    });
    expect(response.body).not.toHaveProperty('password');
    expect(asUser.status).toBe(200);
    expect(asUser.body.id).toBe(seed.user.id);
    expect(asUser.body.teams.map((t: any) => t.id)).toContain(seed.team.id);
  });

  test('POST /api/auth/verify rejects anonymous, invalid and API key callers', async ({
    api,
    apiKey,
  }) => {
    const anonymous = await api.post('/api/auth/verify');
    const garbage = await api.bearer('not-a-token').post('/api/auth/verify');
    const viaApiKey = await apiKey.post('/api/auth/verify');

    expect(anonymous.status).toBe(401);
    expect(garbage.status).toBe(401);
    // API keys are blocked on /api/auth/*.
    expect(viaApiKey.status).toBe(401);
  });

  test('POST /api/auth/logout acknowledges the logout', async ({ api, seed }) => {
    // Use a dedicated session so the shared worker tokens are never touched.
    const token = await login(api, seed.viewer);
    const response = await api.bearer(token).post('/api/auth/logout');

    expect(response.status).toBe(200);
    expect(response.body).toEqual({ ok: true });
    // Without Redis the stateless token remains valid, so no follow-up 401 is asserted.
  });

  test('POST /api/auth/logout requires a session', async ({ api, apiKey }) => {
    const anonymous = await api.post('/api/auth/logout');
    const viaApiKey = await apiKey.post('/api/auth/logout');

    expect(anonymous.status).toBe(401);
    expect(viaApiKey.status).toBe(401);
  });
});

import { test as base, request } from '@playwright/test';
import { ApiClient } from './client';
import { login } from './helpers/auth';
import { SHARE_CONTEXT_HEADER, SHARE_TOKEN_HEADER } from './helpers/constants';
import { readSeedState, type SeedState } from './seed/state';

export interface WorkerTokens {
  admin: string;
  user: string;
  viewer: string;
  apiKey: { id: string; key: string };
}

interface WorkerFixtures {
  /** Seeded entities and dataset metadata written by global setup. */
  seed: SeedState;
  /** Auth tokens created once per worker process. */
  tokens: WorkerTokens;
}

interface TestFixtures {
  /** Unauthenticated client. */
  api: ApiClient;
  /** Logged in as the built-in admin (owns the seeded website, link, pixel, team). */
  admin: ApiClient;
  /** Logged in as the seeded regular user (owns website2, member of the seeded team). */
  user: ApiClient;
  /** Logged in as the seeded view-only user, who owns nothing. */
  viewer: ApiClient;
  /** Authenticated with an admin API key (`umami_…`) instead of a session token. */
  apiKey: ApiClient;
  /** Resolves a share slug to a client authenticated with a share token. */
  share: (slug?: string) => Promise<ApiClient>;
}

export const test = base.extend<TestFixtures, WorkerFixtures>({
  // biome-ignore lint/correctness/noEmptyPattern: Playwright requires the destructuring form
  seed: [async ({}, use) => use(readSeedState()), { scope: 'worker' }],

  tokens: [
    async ({ seed }, use, workerInfo) => {
      const context = await request.newContext({ baseURL: workerInfo.project.use.baseURL });
      const raw = new ApiClient(context);

      try {
        const admin = await login(raw, seed.admin);
        const user = await login(raw, seed.user);
        const viewer = await login(raw, seed.viewer);

        const created = await raw
          .bearer(admin)
          .post('/api/me/api-keys', { name: `api-tests-worker-${workerInfo.workerIndex}` });

        if (created.status !== 200 || !created.body?.key) {
          throw new Error(`Failed to create API key (${created.status}): ${created.text}`);
        }

        const apiKey = { id: created.body.id as string, key: created.body.key as string };

        await use({ admin, user, viewer, apiKey });

        await raw.bearer(admin).del(`/api/me/api-keys/${apiKey.id}`);
      } finally {
        await context.dispose();
      }
    },
    { scope: 'worker' },
  ],

  api: async ({ request }, use) => use(new ApiClient(request)),
  admin: async ({ api, tokens }, use) => use(api.bearer(tokens.admin)),
  user: async ({ api, tokens }, use) => use(api.bearer(tokens.user)),
  viewer: async ({ api, tokens }, use) => use(api.bearer(tokens.viewer)),
  apiKey: async ({ api, tokens }, use) => use(api.bearer(tokens.apiKey.key)),

  share: async ({ api, seed }, use) =>
    use(async (slug = seed.share.slug) => {
      const response = await api.get(`/api/share/${slug}`);

      if (response.status !== 200 || !response.body?.token) {
        throw new Error(`Failed to resolve share ${slug} (${response.status}): ${response.text}`);
      }

      return api.with({
        [SHARE_TOKEN_HEADER]: response.body.token,
        [SHARE_CONTEXT_HEADER]: '1',
      });
    }),
});

export { expect } from '@playwright/test';

import type { ApiClient } from './client';
import { expect, test } from './fixtures';
import { dateRange } from './helpers/dates';

const headers = {
  accept: 'application/json, text/event-stream',
  'mcp-protocol-version': '2026-07-28',
};

async function rpc(client: ApiClient, method: string, params: Record<string, unknown> = {}) {
  const legacy = method === 'initialize';
  const response = await client
    .with({
      ...headers,
      'mcp-method': method,
      ...(typeof params.name === 'string' ? { 'mcp-name': params.name } : {}),
      'mcp-protocol-version': legacy ? '2025-11-25' : '2026-07-28',
    })
    .post('/mcp', {
      jsonrpc: '2.0',
      id: 1,
      method,
      params: legacy
        ? params
        : {
            ...params,
            _meta: {
              'io.modelcontextprotocol/protocolVersion': '2026-07-28',
              'io.modelcontextprotocol/clientInfo': {
                name: 'umami-integration-test',
                version: '1.0.0',
              },
              'io.modelcontextprotocol/clientCapabilities': {},
            },
          },
    });
  expect(response.status, response.text).toBe(200);
  // The transport may return JSON or an SSE message containing the JSON-RPC response.
  const body =
    response.body ??
    response.text
      .split('\n')
      .filter(line => line.startsWith('data:'))
      .map(line => JSON.parse(line.slice(5)))
      .find(message => message.id === 1);
  expect(body?.error).toBeUndefined();
  expect(body?.id).toBe(1);
  return body.result;
}

test.describe('MCP API-key authentication', () => {
  test('rejects anonymous, invalid-key and browser-session callers without OAuth discovery', async ({
    api,
    tokens,
  }) => {
    for (const client of [api, api.bearer('umami_invalid'), api.bearer(tokens.admin)]) {
      const response = await client.with(headers).post('/mcp', {
        jsonrpc: '2.0',
        id: 1,
        method: 'tools/list',
        params: {},
      });
      expect(response.status).toBe(401);
      expect(response.headers['www-authenticate']).toContain('Bearer realm="Umami MCP"');
      expect(response.headers['www-authenticate']).not.toContain('resource_metadata');
    }
  });

  test('initializes, lists read-only tools and queries seeded analytics with an API key', async ({
    apiKey,
    seed,
  }) => {
    const initialized = await rpc(apiKey, 'initialize', {
      protocolVersion: '2025-11-25',
      capabilities: {},
      clientInfo: { name: 'umami-integration-test', version: '1.0.0' },
    });
    expect(initialized.serverInfo.name).toBeTruthy();
    const { tools } = await rpc(apiKey, 'tools/list');
    expect(tools.map(tool => tool.name)).toContain('list_websites');
    expect(tools.map(tool => tool.name)).toContain('get_website_stats');
    expect(tools.every(tool => tool.annotations?.readOnlyHint === true)).toBe(true);

    const websites = await rpc(apiKey, 'tools/call', { name: 'list_websites', arguments: {} });
    expect(websites.isError).not.toBe(true);
    expect(websites.structuredContent.websites.map(website => website.id)).toContain(
      seed.website.id,
    );

    const stats = await rpc(apiKey, 'tools/call', {
      name: 'get_website_stats',
      arguments: {
        websiteId: seed.website.id,
        startAt: new Date(seed.range.startAt).toISOString(),
        endAt: new Date(dateRange(seed).endAt).toISOString(),
      },
    });
    expect(stats.isError).not.toBe(true);
    expect(stats.structuredContent.current.pageviews).toBeGreaterThanOrEqual(
      seed.data.expectedPageviews,
    );
  });

  test('enforces key-owner permissions and rejects a revoked key', async ({ api, user, seed }) => {
    const created = await user.post('/api/me/api-keys', { name: 'mcp-integration-permissions' });
    expect(created.status).toBe(200);
    const keyClient = api.bearer(created.body.key);
    try {
      const argumentsFor = (websiteId: string) => ({
        websiteId,
        startAt: new Date(seed.range.startAt).toISOString(),
        endAt: new Date(dateRange(seed).endAt).toISOString(),
      });
      const own = await rpc(keyClient, 'tools/call', {
        name: 'get_website_stats',
        arguments: argumentsFor(seed.website2.id),
      });
      expect(own.isError).not.toBe(true);
      expect(own.structuredContent.current.pageviews).toBeGreaterThanOrEqual(
        seed.data.expectedWebsite2Pageviews,
      );
      const denied = await rpc(keyClient, 'tools/call', {
        name: 'get_website_stats',
        arguments: argumentsFor(seed.website.id),
      });
      expect(denied.isError).toBe(true);
      expect(denied.structuredContent.error).toMatchObject({ code: 'access_denied', status: 401 });
    } finally {
      expect((await user.del(`/api/me/api-keys/${created.body.id}`)).status).toBe(200);
    }
    const revoked = await keyClient.with(headers).post('/mcp', {
      jsonrpc: '2.0',
      id: 1,
      method: 'tools/list',
      params: {},
    });
    expect(revoked.status).toBe(401);
  });
});

import { serializeAnalyticsQuery } from '../../src/lib/analytics-query';
import { expect, test } from './fixtures';
import { dateRange } from './helpers/dates';
import { uniqueName } from './helpers/entities';

const calculations = [
  ['journey', 'journeys', { steps: 3 }],
  ['retention', 'retention', {}],
  ['breakdown', 'breakdown', { fields: ['path', 'country'] }],
  ['attribution', 'attribution', { model: 'first-click', type: 'path', step: '/pricing' }],
  ['heatmap', 'heatmaps', { mode: 'click', urlPath: '/' }],
  [
    'funnel',
    'funnels/stats',
    {
      window: 60,
      steps: [
        { type: 'path', value: '/' },
        { type: 'path', value: '/pricing' },
      ],
    },
  ],
  ['goal', 'goals/stats', { type: 'path', value: '/' }],
] as const;

// SQL rankings can have ties, so compare result content independently of tied row order.
function canonical(value: any): any {
  if (Array.isArray(value))
    return value.map(canonical).sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b)));
  if (value && typeof value === 'object')
    return Object.fromEntries(
      Object.keys(value)
        .sort()
        .map(key => [key, canonical(value[key])]),
    );
  return value;
}

for (const [type, path, parameters] of calculations) {
  test(`GET ${path} matches legacy ${type} results and access`, async ({
    admin,
    share,
    viewer,
    seed,
  }) => {
    const range = { ...dateRange(seed), timezone: 'UTC', unit: 'day' };
    const body = {
      websiteId: seed.website.id,
      type,
      filters: range,
      parameters: {
        startDate: new Date(range.startAt).toISOString(),
        endDate: new Date(range.endAt).toISOString(),
        timezone: 'UTC',
        unit: 'day',
        ...parameters,
      },
    };
    const url = `/api/websites/${seed.website.id}/${path}`;
    const params = serializeAnalyticsQuery({ ...range, ...parameters });
    const legacy = await admin.post(`/api/reports/${type}`, body);
    const result = await admin.get(url, { params });
    expect(legacy.status).toBe(200);
    expect(result.status).toBe(200);
    expect(canonical(result.body)).toEqual(canonical(legacy.body));
    expect((await viewer.get(url, { params })).status).toBe(401);
    expect((await (await share()).get(url, { params })).status).toBe(
      type === 'heatmap' ? 401 : 200,
    );
    expect((await admin.get(url)).status).toBe(400);
  });
}

for (const [type, parameters] of [
  [
    'funnel',
    {
      window: 60,
      steps: [
        { type: 'path', value: '/' },
        { type: 'event', value: 'signup' },
      ],
    },
  ],
  ['goal', { type: 'path', value: '/' }],
] as const) {
  test(`${type} definitions preserve IDs and scope saved stats to the website`, async ({
    admin,
    viewer,
    share,
    seed,
  }) => {
    const base = `/api/websites/${seed.website.id}/${type}s`;
    const created = await admin.post(base, { name: uniqueName(type), parameters });
    expect(created.status).toBe(200);
    const id = created.body.id;
    try {
      expect((await admin.get(`/api/reports/${id}`)).body.id).toBe(id);
      expect((await admin.get(`${base}/${id}`)).body.parameters).toEqual(parameters);
      expect((await (await share()).get(base)).status).toBe(200);
      const range = dateRange(seed);
      const saved = await admin.get(`${base}/${id}/stats`, { params: range });
      const preview = await admin.get(`${base}/stats`, {
        params: serializeAnalyticsQuery({ ...range, ...parameters }),
      });
      expect(saved.status).toBe(200);
      expect(saved.body).toEqual(preview.body);
      expect((await viewer.post(`${base}/${id}`, { name: 'Denied', parameters })).status).toBe(401);
      const otherBase = `/api/websites/${seed.website2.id}/${type}s/${id}`;
      expect((await admin.get(otherBase)).status).toBe(404);
      expect((await admin.post(otherBase, { name: 'Wrong website', parameters })).status).toBe(404);
      expect((await admin.del(otherBase)).status).toBe(404);
      const otherType = type === 'goal' ? 'funnels' : 'goals';
      expect((await admin.get(`/api/websites/${seed.website.id}/${otherType}/${id}`)).status).toBe(
        404,
      );
      const updated = await admin.post(`${base}/${id}`, {
        name: 'Updated',
        websiteId: seed.website2.id,
        type: otherType,
        parameters,
      });
      expect(updated.status).toBe(200);
      expect(updated.body).toMatchObject({ id, name: 'Updated', websiteId: seed.website.id, type });
    } finally {
      expect((await admin.del(`${base}/${id}`)).status).toBe(200);
    }
    expect((await admin.get(`${base}/${id}`)).status).toBe(404);
  });
}

test('performance and UTM datasets reproduce legacy aggregates', async ({
  admin,
  viewer,
  share,
  seed,
}) => {
  const range = { ...dateRange(seed), timezone: 'UTC', unit: 'day' };
  const body = (type: string) => ({
    websiteId: seed.website.id,
    type,
    filters: range,
    parameters: {
      startDate: new Date(range.startAt).toISOString(),
      endDate: new Date(range.endAt).toISOString(),
      timezone: 'UTC',
      unit: 'day',
      metric: 'lcp',
    },
  });
  const base = `/api/websites/${seed.website.id}`;
  const performance = await admin.post('/api/reports/performance', body('performance'));
  expect(performance.status).toBe(200);
  for (const [path, key] of [
    ['performance/stats', 'summary'],
    ['performance/chart', 'chart'],
  ] as const) {
    const response = await admin.get(`${base}/${path}`, { params: range });
    expect(response.status).toBe(200);
    expect(canonical(key === 'chart' ? response.body.chart : response.body)).toEqual(
      canonical(performance.body[key]),
    );
    expect((await viewer.get(`${base}/${path}`, { params: range })).status).toBe(401);
    expect((await (await share()).get(`${base}/${path}`, { params: range })).status).toBe(200);
  }
  for (const [type, key] of [
    ['path', 'pages'],
    ['title', 'pageTitles'],
    ['device', 'devices'],
    ['browser', 'browsers'],
  ]) {
    const response = await admin.get(`${base}/performance/metrics`, { params: { ...range, type } });
    expect(response.status).toBe(200);
    expect(canonical(response.body)).toEqual(canonical(performance.body[key]));
  }
  const utm = await admin.post('/api/reports/utm', body('utm'));
  expect(utm.status).toBe(200);
  for (const type of ['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content']) {
    const response = await admin.get(`${base}/utm/metrics`, { params: { ...range, type } });
    expect(response.status).toBe(200);
    expect(canonical(response.body)).toEqual(canonical(utm.body[type]));
  }
  expect(
    (await admin.get(`${base}/utm/metrics`, { params: { ...range, type: 'invalid' } })).status,
  ).toBe(400);
  expect(
    (await admin.get(`${base}/performance/metrics`, { params: { ...range, type: 'invalid' } }))
      .status,
  ).toBe(400);
});

import { Client } from '@modelcontextprotocol/client';
import { InMemoryTransport } from '@modelcontextprotocol/server';
import { UmamiClient } from '@umami/api-client';
import { afterEach, beforeEach, describe, expect, test } from 'vitest';
import type { McpLogEvent } from './lib/logger';
import { createUmamiMcpServer } from './server';

const WEBSITE_ID = '6f2a7e0e-2b0f-4b3f-9f0a-1234567890ab';
const SESSION_ID = '0b3b6c2e-1f4a-4d0c-9a5e-abcdefabcdef';
const FUNNEL_ID = '1a2b3c4d-0000-4000-8000-000000000001';
const GOAL_ID = '1a2b3c4d-0000-4000-8000-000000000002';

type Handler = (url: URL, init?: RequestInit) => { status?: number; body: unknown };

interface Call {
  url: URL;
  init?: RequestInit;
}

function createHarness(handler: Handler) {
  const calls: Call[] = [];
  const logs: McpLogEvent[] = [];
  const umami = new UmamiClient({
    baseUrl: 'https://example.com/api',
    token: '[REDACTED]',
    fetch: async (input, init) => {
      const url = new URL(input.toString());
      calls.push({ url, init });
      const { status = 200, body } = handler(url, init);

      return new Response(JSON.stringify(body), {
        status,
        headers: { 'content-type': 'application/json' },
      });
    },
  });
  const server = createUmamiMcpServer({
    client: umami,
    logger: { info: event => logs.push(event), error: event => logs.push(event) },
  });
  const client = new Client({ name: 'test', version: '0.0.0' });

  return { server, client, calls, logs };
}

async function connect(harness: ReturnType<typeof createHarness>) {
  const [clientTransport, serverTransport] = InMemoryTransport.createLinkedPair();

  await harness.server.connect(serverTransport);
  await harness.client.connect(clientTransport);
}

describe('createUmamiMcpServer', () => {
  let harness: ReturnType<typeof createHarness>;

  const routes: Handler = url => {
    const path = url.pathname;

    if (path === '/api/websites') {
      return {
        body: {
          data: [
            { id: WEBSITE_ID, name: 'Umami', domain: 'umami.is', teamId: null, createdAt: null },
          ],
          count: 1,
          page: 1,
          pageSize: 20,
        },
      };
    }

    if (path === `/api/websites/${WEBSITE_ID}/stats`) {
      return {
        body: {
          pageviews: 100,
          visitors: 40,
          visits: 50,
          bounces: 10,
          totaltime: 5000,
          comparison: { pageviews: 80, visitors: 30, visits: 40, bounces: 8, totaltime: 4000 },
        },
      };
    }

    if (path === `/api/websites/${WEBSITE_ID}/pageviews`) {
      return {
        body: {
          pageviews: [{ x: '2024-01-01', y: 10 }],
          sessions: [{ x: '2024-01-01', y: 5 }],
        },
      };
    }

    if (path === `/api/websites/${WEBSITE_ID}/metrics`) {
      return {
        body: [
          { x: '/', y: 50 },
          { x: '/docs', y: 20 },
        ],
      };
    }

    if (path === `/api/websites/${WEBSITE_ID}/active`) {
      return { body: { visitors: 7 } };
    }

    if (path === `/api/websites/${WEBSITE_ID}/events`) {
      return {
        body: {
          data: [
            {
              id: 'e1',
              sessionId: SESSION_ID,
              createdAt: '2024-01-01T00:00:00.000Z',
              eventName: 'signup',
              eventType: 2,
              urlPath: '/signup',
            },
          ],
          count: 250,
          page: Number(url.searchParams.get('page') ?? 1),
          pageSize: Number(url.searchParams.get('pageSize') ?? 20),
        },
      };
    }

    if (path === `/api/websites/${WEBSITE_ID}/sessions`) {
      return {
        body: {
          data: [{ id: SESSION_ID, browser: 'chrome', firstAt: '2024-01-01T00:00:00.000Z' }],
