  test('registers the expected read-only tools', async () => {
    const { tools } = await harness.client.listTools();
    const names = tools.map(tool => tool.name).sort();

    expect(names).toEqual(
      [
        'list_websites',
        'get_website_daterange',
        'get_website_stats',
        'get_website_traffic',
        'get_website_metrics',
