      },
    });

    expect(result.isError).toBeFalsy();
    expect(result.structuredContent).toMatchObject({
      annotations: [
        { id: 'a1', date: '2024-01-05T00:00:00.000Z', note: 'Launched v2', allDay: true },
      ],
      count: 1,
      hasMore: false,
    });

    const url = harness.calls[0].url;

    expect(url.searchParams.get('startAt')).toBe(String(Date.parse('2024-01-01')));
    expect(url.searchParams.get('search')).toBe('v2');
  });

  test('get_performance returns vitals, and series + breakdown on request', async () => {
    const summary = await harness.client.callTool({
      name: 'get_performance',
      arguments: { websiteId: WEBSITE_ID, startAt: '2024-01-01' },
    });

    expect(summary.isError).toBeFalsy();
    expect(summary.structuredContent).toMatchObject({
      measurements: 500,
      vitals: { lcp: { p75: 2100 }, cls: { p75: 0.05 } },
    });
    expect(summary.structuredContent).not.toHaveProperty('series');
    expect(harness.calls).toHaveLength(1);

    harness.calls.length = 0;

    const detailed = await harness.client.callTool({
      name: 'get_performance',
      arguments: { websiteId: WEBSITE_ID, startAt: '2024-01-01', breakdown: 'path', limit: 10 },
    });

    expect(detailed.isError).toBeFalsy();
    expect(detailed.structuredContent).toMatchObject({
      series: { metric: 'lcp', points: [{ date: '2024-01-01', p75: 2000 }] },
      breakdown: {
        metric: 'lcp',
        type: 'path',
        rows: [{ name: '/slow', p75: 4500, measurements: 40 }],
      },
    });
    expect(harness.calls.map(call => call.url.pathname).sort()).toEqual([
      `/api/websites/${WEBSITE_ID}/performance/chart`,
      `/api/websites/${WEBSITE_ID}/performance/metrics`,
      `/api/websites/${WEBSITE_ID}/performance/stats`,
    ]);
  });

  test('run_funnel sends structured criteria with GET', async () => {
    const result = await harness.client.callTool({
      name: 'run_funnel',
      arguments: {
        websiteId: WEBSITE_ID,
        startAt: '2024-01-01',
        endAt: '2024-01-31',
        steps: [
          { type: 'path', value: '/' },
          { type: 'event', value: 'signup' },
        ],
      },
    });

    expect(result.isError).toBeFalsy();
    expect(result.structuredContent).toMatchObject({
      steps: [
        { step: 1, visitors: 10 },
        { step: 2, visitors: 2, dropped: 8 },
      ],
    });

    const { url, init } = harness.calls[0];
    expect(init?.method).toBe('GET');
    expect(init?.body).toBeUndefined();
    expect(url.pathname).toBe(`/api/websites/${WEBSITE_ID}/funnels/stats`);
    expect(JSON.parse(url.searchParams.get('steps') ?? 'null')).toHaveLength(2);
    expect(url.searchParams.get('window')).toBe('60');
    expect(Number(url.searchParams.get('startAt'))).toBeGreaterThan(0);
  });

  test('get_revenue composes feature APIs without changing its tool output', async () => {
    const result = await harness.client.callTool({
      name: 'get_revenue',
      arguments: {
        websiteId: WEBSITE_ID,
        startAt: '2024-01-01',
        endAt: '2024-01-31',
        currency: 'eur',
        filters: { browser: 'Chrome' },
      },
    });
    expect(result.isError).toBeFalsy();
    expect(result.structuredContent).toMatchObject({
      currency: 'EUR',
      total: { sum: 100, comparison: { sum: 80 } },
      chart: [{ sum: 100 }],
      byCountry: [{ name: 'country', value: 100 }],
      byRegion: [{ name: 'region' }],
      byReferrer: [{ name: 'referrer' }],
      byChannel: [{ name: 'channel' }],
    });
    expect(harness.calls).toHaveLength(6);
    for (const { url, init } of harness.calls) {
      expect(init?.method).toBe('GET');
      expect(url.pathname).toContain(`/websites/${WEBSITE_ID}/revenue/`);
      expect(url.searchParams.get('currency')).toBe('EUR');
      expect(url.searchParams.get('startAt')).toBe(String(Date.parse('2024-01-01')));
    }
  });

  test('maps unauthorized website access to a helpful error', async () => {
    const otherWebsite = '11111111-2222-4333-8444-555555555555';
    const result = await harness.client.callTool({
      name: 'get_realtime',
      arguments: { websiteId: otherWebsite },
    });

    expect(result.isError).toBe(true);
    expect(result.structuredContent).toMatchObject({
      error: { code: 'access_denied', status: 401 },
    });
    expect((result.content[0] as { text: string }).text).toContain(otherWebsite);
    expect((result.content[0] as { text: string }).text).not.toContain('secret-token');
  });

  test('logs tool calls without leaking tokens', async () => {
    await harness.client.callTool({ name: 'list_websites', arguments: {} });

    expect(harness.logs).toHaveLength(1);
    expect(harness.logs[0]).toMatchObject({ event: 'tool_call', tool: 'list_websites', ok: true });
    expect(JSON.stringify(harness.logs)).not.toContain('secret-token');
  });
});

import { beforeEach, describe, expect, test, vi } from 'vitest';
import { checkApiKeyAuth } from '@/lib/auth';
import { authenticateMcpRequest, mcpAuthErrorResponse } from './auth';

vi.mock('@/lib/auth', () => ({
  getBearerToken: (request: Request) => request.headers.get('authorization')?.split(' ')[1],
  checkApiKeyAuth: vi.fn(),
}));

const checkApiKeyAuthMock = vi.mocked(checkApiKeyAuth);

function request(token?: string) {
  return new Request('https://analytics.example.com/mcp', {
    method: 'POST',
    headers: token ? { authorization: `Bearer ${token}` } : {},
  });
}

beforeEach(() => {
  vi.unstubAllEnvs();
  vi.stubEnv('CLOUD_MODE', '');
  checkApiKeyAuthMock.mockReset();
});

describe('authenticateMcpRequest', () => {
  test('rejects missing tokens with an API key challenge', async () => {
    const result = await authenticateMcpRequest(request());
    const response = mcpAuthErrorResponse(result);

    expect(response.status).toBe(401);
    expect(response.headers.get('www-authenticate')).toBe(
      'Bearer realm="Umami MCP", error="invalid_request"',
    );
    expect(response.headers.get('cache-control')).toBe('no-store');
  });

  test.each(['not-a-token', 'not-a-key'])(
    'rejects non-API-key credentials: %s',
    async token => {
      await expect(authenticateMcpRequest(request(token))).resolves.toMatchObject({
        ok: false,
        status: 401,
      });
      expect(checkApiKeyAuthMock).not.toHaveBeenCalled();
    },
  );

  test('accepts self-hosted API keys and preserves owner identity', async () => {
    checkApiKeyAuthMock.mockResolvedValue({
      token: 'umami_key',
      user: { id: 'user-1' },
      apiKey: { id: 'key-1', name: 'MCP' },
    } as never);

    await expect(authenticateMcpRequest(request('umami_key'))).resolves.toMatchObject({
      ok: true,
      userId: 'user-1',
      authInfo: {
        token: 'umami_key',
        clientId: 'api-key:key-1',
        scopes: [],
        extra: { userId: 'user-1', authType: 'api-key' },
      },
    });
  });

  test('rejects revoked or unknown keys', async () => {
    checkApiKeyAuthMock.mockResolvedValue(null);
    await expect(authenticateMcpRequest(request('umami_revoked'))).resolves.toMatchObject({
      ok: false,
      status: 401,
      error: 'invalid_token',
    });
  });

  test('rejects self-hosted keys in Cloud mode', async () => {
    vi.stubEnv('CLOUD_MODE', '1');
    await expect(authenticateMcpRequest(request('umami_key'))).resolves.toMatchObject({
      ok: false,
      status: 401,
    });
    expect(checkApiKeyAuthMock).not.toHaveBeenCalled();
  });
});

import type { ApiClient } from '../client';

export interface Credentials {
  username: string;
  password: string;
}

export async function login(api: ApiClient, { username, password }: Credentials) {
  const response = await api.post('/api/auth/login', { username, password });

  if (response.status !== 200 || !response.body?.token) {
    throw new Error(`Login failed for ${username} (${response.status}): ${response.text}`);
  }

  return response.body.token as string;
}

import { SEED_IDS } from './ids';

/**
 * Deterministic analytics dataset ingested through the real collection
 * endpoints (/api/send, /api/batch, /api/record). Works for both Postgres and
 * ClickHouse. Backdated events use `timestamp` (seconds).
 *
 * IPs are private on purpose: the test image has no GeoLite database and
 * src/lib/detect.ts throws on a non-local IP lookup.
 */

export interface SendPayload {
  type: 'event' | 'identify' | 'performance';
  payload: Record<string, unknown>;
}

export interface RecordPayload {
  type: 'record' | 'heatmap';
  payload: Record<string, unknown>;
}

/** Events sent sequentially, chained with the `x-umami-cache` token. */
export interface Visit {
  events: SendPayload[];
}

export interface Dataset {
  range: { startAt: number; endAt: number };
  visits: Visit[];
  batch: SendPayload[];
  replay: { pageview: SendPayload; record: RecordPayload; heatmap: RecordPayload };
  realtime: SendPayload[];
  expected: { pageviews: number; website2Pageviews: number };
  distinctIds: string[];
  pages: string[];
  eventNames: string[];
}

export interface Persona {
  id: string;
  ip: string;
  userAgent: string;
  screen: string;
  language: string;
  referrer: string;
  utm?: boolean;
  tag?: string;
}

export const HOSTNAME = 'example.test';
export const CURRENCY = 'USD';
export const DAYS = 7;
export const EVENT_NAMES = ['signup', 'purchase', 'download'];
export const UTM_QUERY = 'utm_source=newsletter&utm_medium=email&utm_campaign=launch&gclid=abc123';

/** The first N personas send `identify` calls and carry a distinct id. */
const IDENTIFIED_PERSONAS = 3;
const DAY = 86_400;
const HOUR = 3_600;

export const PAGES = [
  { url: '/', title: 'Home' },
  { url: '/pricing', title: 'Pricing' },
  { url: '/blog/hello-world', title: 'Hello World' },
  { url: '/docs', title: 'Documentation' },
  { url: '/signup', title: 'Sign up' },
];

