      expect(stale.status).toBe(401);
      expect(issued.status).toBe(200);
      expect(issued.body.user.id).toBe(userId);
      expect(oldLogin.status).toBe(401);
      expect(fresh.status).toBe(200);
      expect(fresh.body.user.id).toBe(userId);
    });
